import { useState } from 'react';
import { styles } from './styles/styles';
import { activosIniciales, historialIniciales } from './data/datosIniciales';
import Dashboard  from './components/Dashboard';
import Activos    from './components/Activos';
import Asignacion from './components/Asignacion';
import Reporteria from './components/Reporteria';

const NAV = [
  { id: 'dashboard', label: 'Dashboard',  icon: '▦' },
  { id: 'activos',   label: 'Activos',    icon: '◈' },
  { id: 'asignacion',label: 'Asignacion', icon: '⇄' },
  { id: 'reporteria',label: 'Reporteria', icon: '▤' },
];

export default function App() {
  const [pagina,   setPagina]   = useState('dashboard');
  const [activos,  setActivos]  = useState(activosIniciales);
  const [historial,setHistorial]= useState(historialIniciales);

  return (
    <div style={styles.root}>
      <style>{`* { box-sizing: border-box; margin: 0; padding: 0; } select option { background: #1a1a1a; }`}</style>

      <nav style={styles.sidebar}>
        <div style={styles.logo}>
          <div style={styles.logoTitle}>SoporteTech</div>
          <div style={styles.logoSub}>Gestor de Activos TI</div>
        </div>
        {NAV.map(n => (
          <div key={n.id} style={styles.navItem(pagina === n.id)} onClick={() => setPagina(n.id)}>
            <span style={{ fontSize: 16 }}>{n.icon}</span>
            <span>{n.label}</span>
          </div>
        ))}
        <div style={{ flex: 1 }} />
        <div style={{ padding: '16px 20px', fontSize: 11, color: '#333' }}>
          v1.0.0 — Estado de Avance N°1
        </div>
      </nav>

      <main style={styles.main}>
        {pagina === 'dashboard'  && <Dashboard  activos={activos} historial={historial} />}
        {pagina === 'activos'    && <Activos    activos={activos} setActivos={setActivos} setHistorial={setHistorial} />}
        {pagina === 'asignacion' && <Asignacion activos={activos} setActivos={setActivos} historial={historial} setHistorial={setHistorial} />}
        {pagina === 'reporteria' && <Reporteria activos={activos} historial={historial} />}
      </main>
    </div>
  );
}
